this.DlgArr[0] = ["(Глухим шепотом) Стой, где стоишь.","(Медленно поднять руки) Хорошо, хорошо, друг, не нервничай.","(Оттопырить карман куртки, имитируя наличие оружия) Стою.","(Молча броситься на незнакомца)."];
this.DlgArr[1] = ["(Тихий вздох) Кажется, прошли. Растормошил ты их, дурень... Ты кто такой, куда следуешь?","Я — Джек, к базе Терри хотел двинуть, объявление слышал.","Ты пистолет то сначала опусти, тогда поговорим.","С какой стати я должен тебе что-то отвечать, мужик?"];
this.DlgArr[2] = ["Не стоит проверять мои нервы на прочность, парень.","(Вытащить руку из кармана) Опусти пистолет, я безоружен.","(Податься вперед) Оружие опусти, мужик. Медленно.","(Попытаться выбить пистолет из руки ногой)"];
this.DlgArr[4] = ["К базе Терри, говоришь... Нам по пути и тебе не дойти одному. Не хочешь объединиться?","Это было бы здорово. Я согласен.","Что ты знаешь об этой базе?","Уж извини, но я предпочитаю идти один."];
this.DlgArr[5] = ["Время нынче неспокойное, друг. Не обессудь. Я иду в убежище Неаполь. Хочешь — присоединяйся.","С чего мне вдруг доверять тебе?","Убежище Неаполь? Никогда раньше не слышал...","Нет, спасибо, обойдусь."];
this.DlgArr[6] = ["С того, что одного и без оружия тебя быстро распотрошат если не мертвяки, то охотники за наживой, коих немало развелось последнее время. Думай. Я иду в Неаполь, на базу Терри бывшую.","Нам по пути. Но почему я должен тебе доверять?","Я соглашусь лишь при условии, что ты дашь мне оружие.","Справлюсь как-нибудь сам, мистер профи. Счастливо оставаться."];
