package
{
   import com.distriqt.extension.gameservices.GameServices;
   import flash.display.MovieClip;
   import flash.display.StageQuality;
   import flash.events.Event;
   import flash.events.MouseEvent;
   
   public class AddItem extends MovieClip
   {
      
      public var Mov:MovieClip;
      
      public var iType:int;
      
      public var Hist:Object;
      
      public var Main:Object;
      
      private var weapStrings:Array;
      
      private var ForTemn:MovieClip;
      
      public function AddItem(param1:int, param2:Object = null)
      {
         super();
         this.iType = param1;
         this.Hist = param2;
         this.weapStrings = new Array("Ключи от Subaru R1e","Glock 19 Gen4, 5 патронов 9x19 мм","Mark 23, 12 патронов .45 ACP","Армейский нож","Glock 38, 16 патронов .45 G.A.P.","Glock 38, 7 патронов .45 G.A.P.","Remington 870MCS, количество патронов неизвестно","Светошумовая граната CTS Model 7290","Перочинный нож","Desert Eagle Mark XIX, 10 патронов .50 AE","Документы о заражении","Бронежилет PPSS CV1","SIG P250, 9 патронов .357 SIG","Окровавленный зуб, владелец неизвестен","Кухонный нож","Colt М4A1, 30 патронов 5.56х45 мм","Glock 38, 6 патронов .45 G.A.P.","Фонарик");
         addEventListener(Event.ADDED_TO_STAGE,this.OnAdded);
         addEventListener(Event.REMOVED_FROM_STAGE,this.OnRemove);
      }
      
      public function ButExitMouseClick(param1:Object) : void
      {
         this.Main.removeChild(this);
      }
      
      private function OnAdded(param1:Event) : void
      {
         stop();
         removeEventListener(Event.ADDED_TO_STAGE,this.OnAdded);
         this.Main = root;
         this.Main.StageState = 10;
         name = "AddItem";
         this.ForTemn = new TemnMov();
         addChildAt(this.ForTemn,0);
         this.Mov.Txt.text = this.weapStrings[this.iType - 1];
         this.Mov.Weapons.gotoAndStop(this.iType + 1);
         switch(this.iType)
         {
            case 1:
               this.Main.SndPlayer("KeysTake");
               this.Main.TakenKey = true;
               break;
            case 2:
               this.Main.SndPlayer("GlockPickUp");
               this.Main.BulletsNumber = 5;
               break;
            case 3:
               this.Main.SndPlayer("TakeMK23");
               this.Main.BulletsNumber = 12;
               break;
            case 4:
            case 9:
               this.Main.SndPlayer("TakeKnife");
               this.Main.TakenKnife = true;
               break;
            case 5:
               this.Main.SndPlayer("GlockPickUp");
               this.Main.BulletsNumber = 16;
               break;
            case 6:
               this.Main.SndPlayer("GlockPickUp");
               this.Main.BulletsNumber = 7;
               break;
            case 7:
               this.Main.SndPlayer("TakeRemington");
               break;
            case 10:
               this.Main.SndPlayer("DesertTake");
               this.Main.BulletsNumber = 10;
               break;
            case 11:
               this.Main.SndPlayer("DocumentsTake");
               this.Main.TakenDocs = true;
               break;
            case 12:
               this.Main.SndPlayer("BulletproofVest");
               this.Main.TakenArmor = true;
               break;
            case 13:
               this.Main.SndPlayer("Sig250Take");
               break;
            case 15:
               this.Main.SndPlayer("TakeKnife");
               break;
            case 16:
               this.Main.SndPlayer("M4Chamber");
               break;
            case 17:
               this.Main.SndPlayer("GlockPickUp");
               break;
            default:
               this.Main.SndPlayer("WeaponAim");
         }
         if(this.Hist)
         {
            this.Hist.visible = false;
         }
         this.Main.PauseControl.visible = false;
         this.Mov.Weapons.mouseEnabled = false;
         this.Mov.mouseEnabled = this.Mov.Txt.mouseEnabled = false;
         if(Boolean(GameServices.isSupported) && Boolean(GameServices.service.isSignedIn()))
         {
            GameServices.service.achievements.achievementStepsIncrement("CgkIyIig6IIDEAIQDA",1);
            GameServices.service.achievements.achievementStepsIncrement("CgkIyIig6IIDEAIQDQ",1);
         }
         stage.quality = StageQuality.LOW;
         this.Mov.cacheAsBitmap = true;
         gotoAndPlay(2);
      }
      
      private function OnRemove(param1:Event) : void
      {
         this.Main.StageState = 4;
         removeEventListener(Event.REMOVED_FROM_STAGE,this.OnRemove);
         this.Mov.ButExit.removeEventListener(MouseEvent.CLICK,this.ButExitMouseClick);
         this.ForTemn.removeEventListener(MouseEvent.CLICK,this.ButExitMouseClick);
         this.Main.PauseControl.visible = true;
         if(this.Hist)
         {
            this.Hist.visible = true;
         }
      }
   }
}

