   import flash.events.Event;
   import flash.events.MouseEvent;
   
   public class MovCityAuto extends EpisodeMovClass
   {
      
      public var Mov:MovieClip;
      
      public function MovCityAuto(param1:int = 1)
      {
         super(param1);
      }
      
      override protected function MovClickFunc(param1:MouseEvent) : void
      {
         switch(currentFrame)
         {
            default:
               ClearTheSide();
               nextFrame();
               break;
            case 1:
               Main.Item = new NewItem(2,this.Mov.Hist);
               Main.addChildAt(Main.Item,1);
               break;
            case 3:
               Main.Item = new NewItem(5,this.Mov.Hist);
               Main.addChildAt(Main.Item,1);
               break;
            case 5:
               Main.removeChild(Main.PauseControl);
               Main.PauseControl = null;
               Main.StageState = 10;
               mouseEnabled = mouseChildren = false;
               Main.SndPlayer("BrokenGlassSound");
               this.Mov.gotoAndPlay(6);
               break;
            case 7:
               if(iType == 3)
               {
                  Main.Off = new IntoTheOffice();
                  Main.addChildAt(Main.Off,0);
                  Main.removeChild(this);
               }
               else
               {
                  Main.Item = new NewItem(9,this.Mov.Hist);
                  Main.addChildAt(Main.Item,1);
               }
               break;
            case 9:
               Main.Item = new NewItem(3,this.Mov.Hist);
               Main.addChildAt(Main.Item,1);
         }
      }
      
      override protected function OnMovLoad() : void
      {
         switch(iType)
         {
            case 1:
               this.Mov.addEventListener(MouseEvent.CLICK,this.MovClickFunc);
               LoadImage("NewYork.png",this.Mov.Mov,true);
               break;
            case 2:
               gotoAndStop(3);
               break;
            case 3:
               gotoAndStop(7);
               break;
            case 4:
               gotoAndStop(8);
         }
      }
      
      override protected function Checker(param1:Event) : void
      {
         Main.Rezt = new ResultBad(3);
         Main.addChildAt(Main.Rezt,0);
      }
   }
}

