            this.Mov["But" + _loc2_].removeEventListener(MouseEvent.MOUSE_UP,this["But" + _loc2_ + "MouseUpFunc"]);
            _loc2_++;
         }
         stage.dispatchEvent(new Event("RemoveAds"));
         if(!this.Main.getChildByName("AddItem") && Boolean(this.Main.PauseControl))
         {
            if(this.Hist)
