      private function OnAdded(param1:Event) : *
      {
         removeEventListener(Event.ADDED_TO_STAGE,this.OnAdded);
         this.Main = root;
         name = "InGame";
         mouseEnabled = false;
         this.Main.StageState = 9;
         this.i = 1;
         while(this.i < 9)
         {
            if(this.i < 4)
            {
               this["But" + this.i].addEventListener(MouseEvent.CLICK,this["But" + this.i + "MouseClick"]);
            }
            this["Choose" + this.i].addEventListener(MouseEvent.MOUSE_OUT,this["Choose" + this.i + "MouseOutFunc"]);
            this["Choose" + this.i].addEventListener(MouseEvent.MOUSE_OVER,this["Choose" + this.i + "MouseOverFunc"]);
            this["Choose" + this.i].addEventListener(MouseEvent.MOUSE_DOWN,this["Choose" + this.i + "MouseDownFunc"]);
            this["Choose" + this.i].addEventListener(MouseEvent.MOUSE_UP,this["Choose" + this.i + "MouseUpFunc"]);
            this["Choose" + this.i].Txt.mouseEnabled = false;
            ++this.i;
         }
         this.StartTest();
      }
      
