package
{
   import flash.display.MovieClip;
   import flash.events.Event;
   import flash.events.MouseEvent;
   
   public class ToFirstFloor extends EpisodeMovClass
   {
      
      public var Mov:MovieClip;
      
      public function ToFirstFloor(param1:int = 1)
      {
         super(param1);
      }
      
      override protected function MovClickFunc(param1:MouseEvent) : void
      {
         switch(currentFrame)
         {
            default:
               ClearTheSide();
               nextFrame();
               break;
            case 3:
               if(this.Mov.Hist.currentFrame == 1)
               {
                  Main.Item = new NewItem(Main.BulletsNumber > 0 ? 15 : 19,this.Mov.Hist);
                  Main.addChildAt(Main.Item,1);
               }
               else
               {
                  Main.Rezt = new ResultBad(49);
                  Main.addChildAt(Main.Rezt,0);
               }
               break;
            case 4:
               if(Main.LinkedFr)
               {
                  ClearTheSide();
                  gotoAndStop(6);
               }
               else
               {
                  ClearTheSide();
                  nextFrame();
               }
               break;
            case 5:
               Main.Rezt = new ResultBad(46);
               Main.addChildAt(Main.Rezt,0);
               break;
            case 8:
               Main.Rezt = new ResultBad(47);
               Main.addChildAt(Main.Rezt,0);
               break;
            case 9:
               Main.Item = new NewItem(23,this.Mov.Hist);
               Main.addChildAt(Main.Item,1);
               break;
            case 10:
               Main.SndPlayer("ColtShot");
               Main.Rezt = new ResultBad(48);
               Main.addChildAt(Main.Rezt,0);
               break;
            case 11:
            case 12:
               ClearTheSide();
               gotoAndStop(5);
         }
      }
      
      override protected function Checker(param1:Event) : void
      {
         if(currentFrame == 3)
         {
            ClearTheSide();
            if(Main.BulletsNumber == 3)
            {
               gotoAndStop(11);
            }
            else if(Main.BulletsNumber == 2)
            {
               gotoAndStop(12);
            }
            else
            {
               gotoAndStop(4);
            }
         }
         else
         {
            this.Mov.addEventListener(MouseEvent.CLICK,this.MovClickFunc);
         }
      }
      
      override protected function OnMovLoad() : void
      {
         this.Mov.Hist.gotoAndStop(iType);
      }
   }
}

